True def transform(grid):
    out = [row[:] for row in grid]
    # The repeated non-background marker cells define horizontal gaps to fill.
    from collections import Counter
    flat = [v for row in grid for v in row]
    background = Counter(flat).most_common(1)[0][0]
    for r, row in enumerate(grid):
        marker_counts = Counter(v for v in row if v != background)
        for marker, count in marker_counts.items():
            if count >= 2:
                cols = [c for c, v in enumerate(row) if v == marker]
                for c in range(min(cols) + 1, max(cols)):
                    if out[r][c] == background:
                        out[r][c] = 2
    return out
